from datetime import datetime, timezone, timedelta

def parse_offset_aware(s):
    """Parse an offset-aware ISO8601 datetime string."""
    # Python 3.7+ fromisoformat handles offsets like +00:00, +05:30, etc.
    # But 'Z' is not handled by fromisoformat in some versions, so replace it.
    if s is None:
        return None
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    try:
        dt = datetime.fromisoformat(s)
    except (ValueError, AttributeError):
        return None
    # Must be offset-aware (has tzinfo)
    if dt.tzinfo is None:
        return None  # naive due values are skipped
    return dt

def format_utc(dt):
    """Format a datetime as YYYY-MM-DDTHH:MM:SSZ in UTC."""
    utc_dt = dt.astimezone(timezone.utc)
    return utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')

def main():
    data = json.load(open(sys.argv[1]))
    as_of = parse_offset_aware(data["as_of"])
    if as_of is None:
        print(json.dumps([]))
        return

    results = []
    for r in data.get("reminders", []):
        # Skip completed reminders
        if r.get("completed", False):
            continue
        # Parse due value; skip missing, null, or naive
        due_raw = r.get("due")
        if due_raw is None or (isinstance(due_raw, str) and due_raw.strip() == ""):
            continue
        due = parse_offset_aware(due_raw)
        if due is None:
            continue
        # Include only if due AT OR BEFORE as_of (compare actual instants)
        if due <= as_of:
            results.append({
                "id": r["id"],
                "title": r["title"],
                "due_utc": format_utc(due)
            })

    # Sort by actual due instant, then by id
    results.sort(key=lambda x: (parse_offset_aware(x["due_utc"].replace("Z", "+00:00")), x["id"]))

    print(json.dumps(results))

if __name__ == "__main__":
    main()"}

